      "description": "Atomically serialize a JSON value inside the workspace.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "value": "any JSON value"
      },
      "required_arguments": [
        "path",
        "value"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "replace_text": {
      "description": "Replace an exact text occurrence in an existing UTF-8 file.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
        "old": "exact text",
        "new": "replacement",
        "count": "positive integer"
      },
      "required_arguments": [
        "path",
        "old",
        "new"
      ],
      "required_postconditions": [
        "file_exists"
      ]
    },
    "remove_line": {
      "description": "Remove a complete UTF-8 text line from an existing file.",
      "read_only": false,
      "side_effect": true,
      "idempotent": true,
      "default_timeout": 30.0,
      "arguments": {
        "path": "relative path",
